/*     AND DMC.Year =2015      AND DMC.Month=3  ORDER BY 20    20     ORIGINAL--  ORDER BY CodOficina, Fecha, LIN.ItmsGrpCod, Folio, Producto*/  CREATE VIEW dbo.TAI_VW_comision  AS  SELECT        TOP (100) PERCENT LCT.Code AS CodOficina, LCT.Location AS Oficina, DMC.TipoDoc AS TD, DMC.SeriesName AS Serie, DMC.Year AS Año, DMC.Month AS Mes, DAY(DMC.DocDate) AS Dia, DMC.DocDate AS Fecha,                            DMC.DocNum AS NDocSAP, ISNULL(DMC.Indicator, '') AS Ind, DMC.FolioNum AS Folio, DMC.EmployeeName AS Titular, DMC.SlpCode AS CodOperador, DMC.SlpName AS Operador, DMC.CardCode AS CodSN,                            DMC.CardName AS NombreSN, ISNULL(dbo.TAI_FN_agrupacion(CAST(LIN.ItmsGrpCod AS int)), '') AS Grupo, LIN.ItmsGrpCod AS CodLinea, LIN.ItmsGrpNam AS Linea, (CASE WHEN LIN.itmsgrpcod = 103 AND EXISTS                               (SELECT        *                                 FROM            [@tai_prov_prem] PRM                                 WHERE        PRM.Code = ISNULL(SNP.CardCode, '')) AND ltrim(rtrim(isnull(ITM.U_VK_Familia, ' '))) = '10' THEN 'SEMILLAS PREM.' ELSE upper(isnull(GRU.gru_nombre, LIN.ItmsGrpNam)) END) AS SubLinea,                            DMD.ItemCode AS Producto, DMD.Dscription AS Descripción, DMD.Quantity * DMD.NumPerMsr AS Cantidad, (CASE WHEN isnull(dmd.gbctobasunt, 0) = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice)                            ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END) AS Costo, DMD.Quantity * DMD.NumPerMsr * (CASE WHEN isnull(dmd.gbctobasunt, 0) = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice)                            ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END) AS [Costo Total], DMD.WhsCode, ISNULL(ITM.InvntryUom, '') AS UnidadMedida, ISNULL(DMD.INMPriceLC, 0) AS PVUnitNeto,                            (CASE DMD.ObjType WHEN '13' THEN DMD.INMLineTLC WHEN '14' THEN - DMD.INMLineTLC END) AS ImpteNetoML, ISNULL(CASE DMD.ObjType WHEN '13' THEN DMD.Comision WHEN '14' THEN - DMD.Comision END, 0)                            AS Comision, ISNULL(ITM.U_TAI_Envase, '') AS Envase, CASE ITM.U_TAI_UndMed WHEN 'K' THEN 'Kilos' WHEN 'L' THEN 'Litros' ELSE '' END AS KgLt, ISNULL(ITM.U_TAI_Capacidad, 1) AS Capacidad, ISNULL(SNP.CardCode,                            '') AS CodigoProv, ISNULL(SNP.CardName, '') AS NombreProveedor, DMC.CreateDate AS Creacion, (CASE WHEN (DMC.TipoDoc = 'NCV') THEN DMC.CreateDate ELSE DMC.cuartacopia END) AS CuartaCopia,                            ISNULL(ITM.U_TAI_Capacidad, 1) / (CASE WHEN DMD.INMPriceLC = (CASE WHEN isnull(dmd.gbctobasunt, 0) = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END)                            THEN 1 ELSE (DMD.INMPriceLC - (CASE WHEN isnull(dmd.gbctobasunt, 0) = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END)) * (DMD.Quantity * DMD.NumPerMsr)                            END) AS [Comis%], (CASE WHEN LIN.ItmsGrpCod = 117 AND ((((DMD.INMLineTLC - (DMD.Quantity * DMD.NumPerMsr) * (CASE WHEN isnull(dmd.gbctobasunt, 0) = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice)                            ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END))) * 100) / DMD.INMLineTLC) < 2 THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN 0.18 ELSE 0.24 END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3) AND esp_compartir = 'S') THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) THEN                               (SELECT        esp_comision                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) * 0.5 ELSE                               (SELECT        esp_comision                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3) AND esp_compartir = 'N') THEN                               (SELECT        esp_comision                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) WHEN LIN.itmsgrpcod = 103 AND EXISTS                               (SELECT        PRM.U_TAI_PorcCom                                 FROM            [@tai_prov_prem] PRM                                 WHERE        PRM.Code = ISNULL(SNP.CardCode, '')) THEN (CASE WHEN ltrim(rtrim(isnull(ITM.U_VK_Familia, ' '))) = '10' AND ((((DMD.INMLineTLC - (DMD.Quantity * DMD.NumPerMsr) * (CASE WHEN isnull(dmd.gbctobasunt, 0)                            = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END))) * 100) / DMD.INMLineTLC) < 2 THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN 0.18 ELSE 0.24 END) ELSE (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN ISNULL(PLI.U_U_PrctComisVtas2, 0) ELSE ISNULL(PLI.U_PrctComisVtas, 0) END) END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_general                                 WHERE        gen_vendedor = DMC.SlpCode) THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) THEN                               (SELECT        esp_comision                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) ELSE ISNULL(PLI.U_PrctComisVtas, 0) END) WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code) THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode = dmc.SlpCode) THEN                               (SELECT        u_tai_porpropio                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode = dmc.SlpCode) ELSE (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode AND com_comparte = 1) THEN ISNULL(PLI.U_U_PrctComisVtas2, 0) - ((ISNULL(PLI.U_U_PrctComisVtas2, 0) *                               (SELECT        CEJ.U_TAI_DifComMaq                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        (CEJ.Code = LIN.ItmsGrpCod) AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode AND CEJ.U_TAI_DifComMaq <> 100)) / 100) ELSE (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode AND com_comparte = 0) THEN ISNULL(PLI.U_U_PrctComisVtas2, 0) ELSE ISNULL(PLI.U_PrctComisVtas, 0) - ((ISNULL(PLI.U_PrctComisVtas, 0) *                               (SELECT        CEJ.U_TAI_DifComMaq                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        (CEJ.Code = LIN.ItmsGrpCod) AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode AND CEJ.U_TAI_DifComMaq <> 100)) / 100) END) END) END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN ISNULL(PLI.U_U_PrctComisVtas2, 0) ELSE ISNULL(PLI.U_PrctComisVtas, 0) END) AS [Comis%Est], (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN (CASE WHEN DMD.NvoMargen > 0 THEN (DMD.NvoMargen / (DMD.Quantity * DMD.NumPerMsr)) ELSE (DMD.INMPriceLC - (CASE WHEN isnull(dmd.gbctobasunt, 0)                            = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END)) END) ELSE (CASE WHEN LIN.ItmsGrpCod <> 117 THEN (DMD.INMPriceLC - (CASE WHEN isnull(dmd.gbctobasunt,                            0) = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END)) ELSE (CASE WHEN (((DMD.INMPriceLC - (CASE WHEN isnull(dmd.gbctobasunt, 0)                            = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END)) * 100) / ISNULL(DMD.INMPriceLC, 1)) <=                               (SELECT        U_ValorNumerico                                 FROM            [@VK_OPAR]                                 WHERE        Code = 'BASECALM') THEN ABS(CASE DMD.ObjType WHEN '13' THEN ISNULL(DMD.INMPriceLC, 0) WHEN '14' THEN - ISNULL(DMD.INMPriceLC, 0) END) *                               ((SELECT        U_ValorNumerico                                   FROM            [@VK_OPAR]                                   WHERE        Code = 'BASECALM') / 100) ELSE (DMD.INMPriceLC - (CASE WHEN isnull(dmd.gbctobasunt, 0) = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END))                            END) END) END) * (DMD.Quantity * DMD.NumPerMsr) * (CASE WHEN DMC.TipoDoc = 'ncv' THEN - 1 ELSE (CASE WHEN ISNULL(DMD.INMPriceLC, 0) < (CASE WHEN isnull(dmd.gbctobasunt, 0)                            = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END) THEN (CASE WHEN DMC.TipoDoc = 'fvr' THEN 1 ELSE - 1 END) ELSE 1 END) END) AS Margen,                            ISNULL(PLI.U_PrctMargenMin, 0) AS PrctMargenMin, (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) THEN                               (SELECT        esp_comision                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) WHEN LIN.itmsgrpcod = 103 AND EXISTS                               (SELECT        PRM.U_TAI_PorcCom                                 FROM            [@tai_prov_prem] PRM                                 WHERE        PRM.Code = ISNULL(SNP.CardCode, '')) THEN (CASE WHEN ltrim(rtrim(isnull(ITM.U_VK_Familia, ' '))) = '10' AND ((((DMD.INMLineTLC - (DMD.Quantity * DMD.NumPerMsr) * (CASE WHEN isnull(dmd.gbctobasunt, 0)                            = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END))) * 100) / DMD.INMLineTLC) < 2 THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN 0.18 ELSE 0.24 END) ELSE (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN ISNULL(PLI.U_U_PrctComisVtas2, 0) ELSE ISNULL(PLI.U_PrctComisVtas, 0) END) END) WHEN LIN.ItmsGrpCod = 117 AND                            ((((DMD.INMLineTLC - (DMD.Quantity * DMD.NumPerMsr) * (CASE WHEN isnull(dmd.gbctobasunt, 0) = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END))) * 100)                            / DMD.INMLineTLC) < 2 THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN 0.18 ELSE 0.24 END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_general                                 WHERE        gen_vendedor = DMC.SlpCode) THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) THEN                               (SELECT        esp_comision                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) ELSE ISNULL(PLI.U_PrctComisVtas, 0) END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN ISNULL(PLI.U_U_PrctComisVtas2, 0) ELSE ISNULL(PLI.U_PrctComisVtas, 0) END) AS PrctComisVtas, ISNULL(PLI.U_PrctComisEsp, 0) AS PrctComisEsp,                            (CASE WHEN LIN.ItmsGrpCod = 117 AND ((((DMD.INMLineTLC - (DMD.Quantity * DMD.NumPerMsr) * (CASE WHEN isnull(dmd.gbctobasunt, 0) = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt,                            ITW.U_TAI_CostoItem) END))) * 100) / DMD.INMLineTLC) < 2 THEN 'V' WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) THEN                               (SELECT        esp_base                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) WHEN LIN.itmsgrpcod = 103 AND EXISTS                               (SELECT        PRM.U_TAI_PorcCom                                 FROM            [@tai_prov_prem] PRM                                 WHERE        PRM.Code = ISNULL(SNP.CardCode, '')) THEN (CASE WHEN ltrim(rtrim(isnull(ITM.U_VK_Familia, ' '))) = '10' AND ((((DMD.INMLineTLC - (DMD.Quantity * DMD.NumPerMsr) * (CASE WHEN isnull(dmd.gbctobasunt, 0)                            = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END))) * 100) / DMD.INMLineTLC) < 2 THEN 'V' ELSE (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN ISNULL(PLI.U_U_BaseComis2, 0) ELSE ISNULL(PLI.U_BaseComis, 0) END) END) WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code) THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode = dmc.SlpCode) THEN                               (SELECT        U_TAI_Base                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode = dmc.SlpCode) ELSE (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN ISNULL(PLI.U_U_BaseComis2, 'M') ELSE ISNULL(PLI.U_BaseComis, 'M') END) END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN ISNULL(PLI.U_U_BaseComis2, 'M') ELSE ISNULL(PLI.U_BaseComis, 'M') END) AS BaseComis, ISNULL(PLI.U_PrctBajoMargen, 0) AS PrctBajoMargen,                            ISNULL(PLI.U_TAI_TopeComision, 0) AS TopeComision, ISNULL(PLI.U_TAI_PorcFlete, 0) AS PorcFlete, (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_general                                 WHERE        gen_vendedor = DMC.SlpCode) THEN 100 WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3) AND esp_compartir = 'S') THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) THEN 50 ELSE 100 END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3) AND esp_compartir = 'N') THEN 100 WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code) THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode = dmc.SlpCode) THEN 100 ELSE (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode AND com_comparte = 1) THEN                               (SELECT        CEJ.U_TAI_DifComMaq                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode AND CEJ.U_TAI_DifComMaq <> 100) ELSE (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode AND com_comparte = 0) THEN 100 ELSE                               (SELECT        CEJ.U_TAI_DifComMaq                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode AND CEJ.U_TAI_DifComMaq <> 100) END) END) END) ELSE 100 END) AS PrctComiOpEsp,                            (CASE WHEN LIN.itmsgrpcod = 103 AND EXISTS                               (SELECT        PRM.U_TAI_PorcCom                                 FROM            [@tai_prov_prem] PRM                                 WHERE        PRM.Code = ISNULL(SNP.CardCode, '')) THEN (CASE WHEN ltrim(rtrim(isnull(ITM.U_VK_Familia, ' '))) = '10' AND ((((DMD.INMLineTLC - (DMD.Quantity * DMD.NumPerMsr) * (CASE WHEN isnull(dmd.gbctobasunt, 0)                            = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END))) * 100) / DMD.INMLineTLC) < 2 THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN 0.18 ELSE 0.24 END) ELSE (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN ISNULL(PLI.U_U_PrctComisVtas2, 0) ELSE ISNULL(PLI.U_PrctComisVtas, 0) END) END) WHEN LIN.ItmsGrpCod = 117 AND                            ((((DMD.INMLineTLC - (DMD.Quantity * DMD.NumPerMsr) * (CASE WHEN isnull(dmd.gbctobasunt, 0) = 0 THEN isnull(ITW.U_TAI_CostoItem, ITW.avgprice) ELSE isnull(dmd.gbctobasunt, ITW.U_TAI_CostoItem) END))) * 100)                            / DMD.INMLineTLC) < 2 THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN 0.18 ELSE 0.24 END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_general                                 WHERE        gen_vendedor = DMC.SlpCode) THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) THEN                               (SELECT        esp_comision                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) ELSE ISNULL(PLI.U_PrctComisVtas, 0) END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3) AND esp_compartir = 'S') THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) THEN                               (SELECT        esp_comision                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) * 0.5 ELSE                               (SELECT        esp_comision                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3) AND esp_compartir = 'N') THEN                               (SELECT        esp_comision                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3)) WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code) THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode = dmc.SlpCode) THEN                               (SELECT        u_tai_porpropio                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode = dmc.SlpCode) ELSE (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode AND com_comparte = 1) THEN ISNULL(PLI.U_U_PrctComisVtas2, 0) - ((ISNULL(PLI.U_U_PrctComisVtas2, 0) *                               (SELECT        CEJ.U_TAI_DifComMaq                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        (CEJ.Code = LIN.ItmsGrpCod) AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode AND CEJ.U_TAI_DifComMaq <> 100)) / 100) ELSE (CASE WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode AND com_comparte = 0) THEN ISNULL(PLI.U_U_PrctComisVtas2, 0) ELSE ISNULL(PLI.U_PrctComisVtas, 0) - ((ISNULL(PLI.U_PrctComisVtas, 0) *                               (SELECT        CEJ.U_TAI_DifComMaq                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        (CEJ.Code = LIN.ItmsGrpCod) AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode AND CEJ.U_TAI_DifComMaq <> 100)) / 100) END) END) END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode) THEN ISNULL(PLI.U_U_PrctComisVtas2, 0) ELSE ISNULL(PLI.U_PrctComisVtas, 0) END) AS PrctComision, (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code) THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) THEN 1 ELSE 0 END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode AND com_comparte = 0) THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code) THEN 0 ELSE 0 END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_general                                 WHERE        gen_vendedor = DMC.SlpCode) THEN 0 WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3) AND esp_compartir = 'S') THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) THEN 1 ELSE 0 END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3) AND esp_compartir = 'N') THEN 0 ELSE 0 END) AS VtaMarCompartida, (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code) THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) THEN                               (SELECT        CEJ.U_TAI_SlpCode                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) ELSE 0 END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode AND com_comparte = 0) THEN 0 WHEN EXISTS                               (SELECT        *                                 FROM            comision_general                                 WHERE        gen_vendedor = DMC.SlpCode) THEN 0 WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3) AND esp_compartir = 'S') THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) THEN                               (SELECT DISTINCT CEJ.U_TAI_SlpCode                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) ELSE 0 END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3) AND esp_compartir = 'N') THEN 0 ELSE 0 END) AS VtaCodOperador, (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code) THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) THEN                               (SELECT        OPE.SlpName                                 FROM            [@TAI_PPLINSUC] AS CEJ INNER JOIN                                                           OSLP AS OPE ON OPE.SlpCode = CEJ.U_TAI_SlpCode                                 WHERE        CEJ.Code = LIN.ItmsGrpCod AND CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) ELSE '' END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_nuevo                                 WHERE        id_operador = DMC.SlpCode AND com_comparte = 0) THEN '' WHEN EXISTS                               (SELECT        *                                 FROM            comision_general                                 WHERE        gen_vendedor = DMC.SlpCode) THEN '' WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3) AND esp_compartir = 'S') THEN (CASE WHEN EXISTS                               (SELECT        *                                 FROM            [@TAI_PPLINSUC] AS CEJ                                 WHERE        CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) THEN                               (SELECT DISTINCT OPE.SlpName                                 FROM            [@TAI_PPLINSUC] AS CEJ INNER JOIN                                                           OSLP AS OPE ON OPE.SlpCode = CEJ.U_TAI_SlpCode                                 WHERE        CEJ.U_SucCodigo = LCT.Code AND CEJ.U_TAI_SlpCode <> dmc.SlpCode) ELSE '' END) WHEN EXISTS                               (SELECT        *                                 FROM            comision_especifica                                 WHERE        esp_linea = LIN.itmsgrpcod AND esp_bodega = RIGHT(DMD.WhsCode, 3) AND esp_compartir = 'N') THEN '' ELSE '' END) AS VtaNomOperador, ISNULL(DMD.U_TAI_descripcionad, '') AS Descrip,                            DMD.NvoMargen  FROM            dbo.TAI_VW_CabVtas AS DMC INNER JOIN                           dbo.TAI_VW_DetVtas AS DMD ON DMC.ObjType = DMD.ObjType AND DMC.DocEntry = DMD.DocEntry LEFT OUTER JOIN                           dbo.OITB AS LIN ON DMD.itmsgrpcod = LIN.ItmsGrpCod LEFT OUTER JOIN                           dbo.[@TAI_PPLIN] AS PLI ON PLI.Code = LIN.ItmsGrpCod LEFT OUTER JOIN                           dbo.presupuesto_agrupacion AS AGR ON AGR.id_agrupacion = PLI.U_TAI_Agrupacion LEFT OUTER JOIN                           dbo.presupuesto_grupo AS GRU ON GRU.id_grupo = PLI.U_TAI_Grupo LEFT OUTER JOIN                           dbo.OHEM AS EMT ON DMC.OwnerCode = EMT.empID LEFT OUTER JOIN                           dbo.OUBR AS OFT ON EMT.branch = OFT.Code LEFT OUTER JOIN                           dbo.OHEM AS EMO ON DMC.SlpCode = EMO.salesPrson LEFT OUTER JOIN                           dbo.OUBR AS OFO ON EMO.branch = OFO.Code LEFT OUTER JOIN                           dbo.OITM AS ITM ON DMD.ItemCode = ITM.ItemCode LEFT OUTER JOIN                           dbo.OCRD AS SNP ON ITM.CardCode = SNP.CardCode LEFT OUTER JOIN                           dbo.OITW AS ITW ON ITW.ItemCode = DMD.ItemCode AND ITW.WhsCode = DMD.WhsCode LEFT OUTER JOIN                           dbo.OWHS AS WHS ON WHS.WhsCode = DMD.WhsCode LEFT OUTER JOIN                           dbo.OLCT AS LCT ON LCT.Code = WHS.Location  WHERE        (1 = 1) AND (DMC.ObjType IN ('13', '14')) AND (DMD.INMPriceLC > 0) AND (ISNULL(dbo.TAI_FN_agrupacion(CAST(LIN.ItmsGrpCod AS int)), N'') <> '') AND (DMD.WhsCode <> '00')  
CREATE VIEW dbo.VK_VW_ODOC  AS  /* Facturas Cliente */ SELECT T0.ObjType[ObjType], T0.DocEntry[DocEntry], T0.TransId[TransId], T0.DocNum[DocNum], T0.DocType[DocType], T0.DocSubType[SubType],                            CASE T0.DocSubType WHEN '--' THEN CASE T0.IsIns WHEN 'Y' THEN 'FVR' ELSE 'FV ' END WHEN 'DN' THEN 'NDV' WHEN 'IE' THEN 'FVE' /* Factura Exenta */ WHEN 'IB' THEN 'BV ' WHEN 'EB' THEN 'BVE' WHEN 'IX' THEN 'FVX'                            /* Factura Exportación */ WHEN 'IR' THEN 'FVP' /* Factura y Pago */ WHEN 'IB' THEN 'BV ' WHEN 'RI' THEN 'FVR' /* Factura Reservada */ END [TipoDoc], STR(YEAR(T0.DocDate), 4, 0) + '-' + REPLACE(STR(MONTH(T0.DocDate),                            2, 0), ' ', 0) [Periodo], YEAR(T0.DocDate) [Year], MONTH(T0.DocDate) [Month], DATEPART(quarter, T0.DocDate) [Quarter], YEAR(T0.DocDate + (- DATEPART(dw, T0.DocDate) + 4)) [YearW], MONTH(T0.DocDate + (- DATEPART(dw,                            T0.DocDate) + 4)) [MonthW], DATEPART(week, T0.DocDate) - 1 [Week], T0.Series[Series], ND.SeriesName[SeriesName], T0.FolioPref[FolioPref], T0.FolioNum[FolioNum], T0.NumAtCard[NumAtCard], T0.CardCode[CardCode],                            T0.CardName[CardName], T0.DocDate[DocDate], T0.DocDueDate[DueDate], T0.TaxDate[TaxDate], T0.DocTotal[DocTotalLC], T0.DocCur[DocCurr], T0.DocRate[DocRate], T0.DocTotalFC[DocTotalFC], T0.DocTotalSy[DocTotalSC],                            T0.VatSum[VatSumLC], T0.VatSumFC[VatSumFC], T0.VatSumSy[VatSumSC], T0.DocTotal - T0.VatSum[DocNetSumLC]/* Importe sin IVA ML*/ , T0.DocTotalFC - T0.VatSumFC[DocNetSumFC]/* Importe sin IVA ME*/ ,                            T0.DocTotalSy - T0.VatSumSy[DocNetSumSC]/* Importe sin IVA MS*/ , T0.PaidToDate[DocPaidLC]/* Importe Pagado ML*/ , T0.PaidFC[DocPaidFC]/* Importe Pagado ME*/ , T0.PaidSys[DocPaidSC]/* Importe Pagado MS*/ ,                            T0.DocTotal - T0.PaidToDate[DocBalSumLC]/* Importe Pendiente ML*/ , T0.DocTotalFC - T0.PaidFC[DocBalSumFC]/* Importe Pendiente ME*/ , T0.DocTotalSy - T0.PaidSys[DocBalSumSC]/* Importe Pendiente MS*/ ,                            T0.DiscPrcnt[DiscPrcnt], T0.DiscSum[DiscSumLC], T0.DiscSumFC[DiscSumFC], T0.RoundDif[RoundDifLC], T0.RoundDifFC[RoundDifFC], T0.RoundDifSy[RoundDifSC], T0.SlpCode[SlpCode], S0.SlpName[SlpName],                            T0.OwnerCode[OwnerCode], EM.LastName + EM.FirstName[EmployeeName], BR.Name[Branch], T0.GroupNum[PymTermCod], PG.PymntGroup[PymTermNam], T0.Project[Project], PR.PrjName[PrjName], T0.Indicator[Indicator],                            ID.Name[IndName], T0.LicTradNum[LicTradNum], T0.CreateDate[CreateDate], T0.UserSign[UserSign], T0.JrnlMemo[JrnlMemo], T0.Comments[Comments], T0.ReceiptNum[ReceiptNum], T0.CtlAccount[BPAcctCode],                            AC.FormatCode[BPActFrmtCode], AC.AcctName[BPAcctName], T0.WddStatus[WddStatus]/* Estado Procedimiento de autorización */ , T0.UserSign2[UserSign2], T0.ExtraDays  FROM            OINV T0 WITH (NOLOCK) JOIN                           NNM1 ND WITH (NOLOCK) ON T0.Series = ND.Series LEFT JOIN                           OSLP S0 WITH (NOLOCK) ON T0.SlpCode = S0.SlpCode LEFT JOIN                           OCTG PG WITH (NOLOCK) ON T0.GroupNum = PG.GroupNum LEFT JOIN                           OHEM EM WITH (NOLOCK) ON T0.OwnerCode = EM.EmpId LEFT JOIN                           OUBR BR WITH (NOLOCK) ON EM.Branch = BR.Code LEFT JOIN                           OPRJ PR WITH (NOLOCK) ON T0.Project = PR.PrjCode LEFT JOIN                           OIDC ID WITH (NOLOCK) ON T0.Indicator = ID.Code LEFT JOIN                           OACT AC WITH (NOLOCK) ON T0.CtlAccount = AC.AcctCode  WHERE        1 = 1 AND ISNULL(T0.U_U_TAI_OVTA, 0) <> 1  UNION ALL  /* Notas Crédito Cliente */ SELECT T0.ObjType[ObjType], T0.DocEntry[DocEntry], T0.TransId[TransId], T0.DocNum[DocNum], T0.DocType[DocType], T0.DocSubType[SubType], 'NCV' [TipoDoc], STR(YEAR(T0.DocDate), 4, 0)                            + '-' + REPLACE(STR(MONTH(T0.DocDate), 2, 0), ' ', 0) [Periodo], YEAR(T0.DocDate) [Year], MONTH(T0.DocDate) [Month], DATEPART(quarter, T0.DocDate) [Quarter], YEAR(T0.DocDate + (- DATEPART(dw, T0.DocDate) + 4)) [YearW],                            MONTH(T0.DocDate + (- DATEPART(dw, T0.DocDate) + 4)) [MonthW], DATEPART(week, T0.DocDate) - 1 [Week], T0.Series[Series], ND.SeriesName[SeriesName], T0.FolioPref[FolioPref], T0.FolioNum[FolioNum],                            T0.NumAtCard[NumAtCard], T0.CardCode[CardCode], T0.CardName[CardName], T0.DocDate[DocDate], T0.DocDueDate[DueDate], T0.TaxDate[TaxDate], T0.DocTotal[DocTotalLC], T0.DocCur[DocCurr], T0.DocRate[DocRate],                            T0.DocTotalFC[DocTotalFC], T0.DocTotalSy[DocTotalSC], T0.VatSum[VatSumLC], T0.VatSumFC[VatSumFC], T0.VatSumSy[VatSumSC], T0.DocTotal - T0.VatSum[DocNetSumLC]/* Importe sin IVA ML*/ ,                            T0.DocTotalFC - T0.VatSumFC[DocNetSumFC]/* Importe sin IVA ME*/ , T0.DocTotalSy - T0.VatSumSy[DocNetSumSC]/* Importe sin IVA MS*/ , T0.PaidToDate[DocPaidLC]/* Importe Pagado ML*/ ,                            T0.PaidFC[DocPaidFC]/* Importe Pagado ME*/ , T0.PaidSys[DocPaidSC]/* Importe Pagado MS*/ , T0.DocTotal - T0.PaidToDate[DocBalSumLC]/* Importe Pendiente ML*/ ,                            T0.DocTotalFC - T0.PaidFC[DocBalSumFC]/* Importe Pendiente ME*/ , T0.DocTotalSy - T0.PaidSys[DocBalSumSC]/* Importe Pendiente MS*/ , T0.DiscPrcnt[DiscPrcnt], T0.DiscSum[DiscSumLC], T0.DiscSumFC[DiscSumFC],                            T0.RoundDif[RoundDifLC], T0.RoundDifFC[RoundDifFC], T0.RoundDifSy[RoundDifSC], T0.SlpCode[SlpCode], S0.SlpName[SlpName], T0.OwnerCode[OwnerCode], EM.LastName + EM.FirstName[EmployeeName],                            BR.Name[Branch], T0.GroupNum[PymTermCod], PG.PymntGroup[PymTermNam], T0.Project[Project], PR.PrjName[PrjName], T0.Indicator[Indicator], ID.Name[IndName], T0.LicTradNum[LicTradNum], T0.CreateDate[CreateDate],                            T0.UserSign[UserSign], T0.JrnlMemo[JrnlMemo], T0.Comments[Comments], T0.ReceiptNum[ReceiptNum], T0.CtlAccount[BPAcctCode], AC.FormatCode[BPActFrmtCode], AC.AcctName[BPAcctName],                            T0.WddStatus[WddStatus]/* Estado Procedimiento de autorización */ , T0.UserSign2[UserSign2], T0.ExtraDays  FROM            ORIN T0 WITH (NOLOCK) JOIN                           NNM1 ND WITH (NOLOCK) ON T0.Series = ND.Series LEFT JOIN                           OSLP S0 WITH (NOLOCK) ON T0.SlpCode = S0.SlpCode LEFT JOIN                           OCTG PG WITH (NOLOCK) ON T0.GroupNum = PG.GroupNum LEFT JOIN                           OHEM EM WITH (NOLOCK) ON T0.OwnerCode = EM.EmpId LEFT JOIN                           OUBR BR WITH (NOLOCK) ON EM.Branch = BR.Code LEFT JOIN                           OPRJ PR WITH (NOLOCK) ON T0.Project = PR.PrjCode LEFT JOIN                           OIDC ID WITH (NOLOCK) ON T0.Indicator = ID.Code LEFT JOIN                           OACT AC WITH (NOLOCK) ON T0.CtlAccount = AC.AcctCode  WHERE        1 = 1  UNION ALL  /* Facturas Anticipo Cliente */ SELECT T0.ObjType[ObjType], T0.DocEntry[DocEntry], T0.TransId[TransId], T0.DocNum[DocNum], T0.DocType[DocType], T0.DocSubType[SubType], 'FVA' [TipoDoc], STR(YEAR(T0.DocDate), 4, 0)                            + '-' + REPLACE(STR(MONTH(T0.DocDate), 2, 0), ' ', 0) [Periodo], YEAR(T0.DocDate) [Year], MONTH(T0.DocDate) [Month], DATEPART(quarter, T0.DocDate) [Quarter], YEAR(T0.DocDate + (- DATEPART(dw, T0.DocDate) + 4)) [YearW],                            MONTH(T0.DocDate + (- DATEPART(dw, T0.DocDate) + 4)) [MonthW], DATEPART(week, T0.DocDate) - 1 [Week], T0.Series[Series], ND.SeriesName[SeriesName], T0.FolioPref[FolioPref], T0.FolioNum[FolioNum],                            T0.NumAtCard[NumAtCard], T0.CardCode[CardCode], T0.CardName[CardName], T0.DocDate[DocDate], T0.DocDueDate[DueDate], T0.TaxDate[TaxDate], T0.DocTotal[DocTotalLC], T0.DocCur[DocCurr], T0.DocRate[DocRate],                            T0.DocTotalFC[DocTotalFC], T0.DocTotalSy[DocTotalSC], T0.VatSum[VatSumLC],